void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    const double ACT_LIMIT = 1e120;
    if (newAct > ACT_LIMIT) {
        double scale = 1e-120;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
        newAct = activity[var] + inc; // recompute after scaling
    }
    activity[var] = newAct;
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
